s=s.replace('    size = _env("IMAGE_SIZE") or _settings_value(settings, "image_size") or DEFAULT_SIZE\n    return {\n        "base_url": base_url.rstrip("/"),\n        "api_key": api_key,\n        "model": model,\n        "size": size,\n    }', '    size = _env("IMAGE_SIZE") or _settings_value(settings, "image_size") or DEFAULT_SIZE\n    api_style = (_env("IMAGE_API_STYLE") or _settings_value(settings, "image_api_style") or "auto").lower()\n    if api_style == "auto":\n        api_style = "tokendance" if "tokendance.space" in base_url.lower() else "openai-compatible"\n    return {\n        "base_url": base_url.rstrip("/"),\n        "api_key": api_key,\n        "model": model,\n        "size": size,\n        "api_style": api_style,\n    }')
s=s.replace('    negative: str,\n) -> dict[str, Any]:', '    negative: str,\n    api_style: str = "openai-compatible",\n) -> dict[str, Any]:')
old='''    return {\n        "model": model,\n        "prompt": prompt,\n        "n": 1,\n        "size": size,\n        "seed": int(seed),\n        "response_format": "b64_json",\n        "negative_prompt": negative,\n        "negative": negative,\n        "watermark": False,\n    }'''
