p=root/'backend/app/providers/video.py'
s=p.read_text(encoding='utf-8')
s=s.replace('    ratio = _env("VIDEO_RATIO") or _settings_value(settings, "video_ratio") or DEFAULT_RATIO\n    return {\n        "base_url": base_url.rstrip("/"),\n        "api_key": api_key,\n        "model": model,\n        "resolution": resolution,\n        "ratio": ratio,\n    }', '    ratio = _env("VIDEO_RATIO") or _settings_value(settings, "video_ratio") or DEFAULT_RATIO\n    api_style = (_env("VIDEO_API_STYLE") or _settings_value(settings, "video_api_style") or "auto").lower()\n    if api_style == "auto":\n        api_style = "tokendance" if "tokendance.space" in base_url.lower() else "volcengine"\n    poll_interval = int(_env("VIDEO_POLL_INTERVAL") or _settings_value(settings, "video_poll_interval") or "5")\n    timeout = int(_env("VIDEO_TIMEOUT") or _settings_value(settings, "video_timeout") or "1800")\n    return {\n        "base_url": base_url.rstrip("/"), "api_key": api_key, "model": model,\n        "resolution": resolution, "ratio": ratio, "api_style": api_style,\n        "poll_interval": poll_interval, "timeout": timeout,\n    }')
s=s.replace('        self.ratio = normalize_ratio(str(resolved["ratio"]))\n        if not self.api_key:', '        self.ratio = normalize_ratio(str(resolved["ratio"]))\n        self.api_style = resolved["api_style"]\n        self.poll_interval = max(1, int(resolved["poll_interval"]))\n        self.timeout = max(30, int(resolved["timeout"]))\n        if not self.api_key:')
s=s.replace('        payload = build_video_payload(\n', '        if self.api_style == "tokendance":\n            return self._generate_tokendance(shot, frame_path, output_dir, prompt, seed, duration, resolution)\n        payload = build_video_payload(\n')
marker='\n\ndef build_provider(settings: Any = None) -> CloudVideoProvider:\n'
helper='''\n\n    def _generate_tokendance(self, shot, frame_path, output_dir, prompt, seed, duration, resolution):\n        target = Path(output_dir); target.mkdir(parents=True, exist_ok=True)\n        body = {"model": self.model, "resolution": str(resolution).upper(), "duration": duration, "content": [\n            {"type": "text", "text": prompt},\n            {"type": "image_url", "image_url": {"url": image_to_data_url(frame_path)}, "role": "first_frame"},\n        ]}\n        task_url = f"{self.base_url}/video_generation"\n        submitted = self._tokendance_request(task_url, "POST", body)\n        task_id = submitted.get("task_id") or submitted.get("id")\n        if not task_id: raise VideoSubmitUnconfirmed("TokenDance 图生视频提交未返回 task_id")\n        deadline = time.time() + self.timeout; video_url = ""\n        while time.time() < deadline:\n            time.sleep(self.poll_interval)\n            payload = self._tokendance_request(f"{self.base_url}/query/video_generation/{urllib.parse.quote(str(task_id))}", "GET", None)\n            task = payload.get("task") if isinstance(payload.get("task"), dict) else payload\n            status = str(task.get("status") or "").lower()\n            if status == "succeeded":\n                content = task.get("content") or {}; video_url = str(content.get("url") or task.get("url") or ""); break\n            if status in {"failed", "cancelled", "canceled", "expired"}: raise RuntimeError(f"TokenDance 图生视频失败: {status} {task.get('error') or ''}".strip())\n        if not video_url: raise VideoSubmitUnconfirmed(f"TokenDance 图生视频超时或未返回视频 URL: {task_id}")\n        shot_id = str(shot.get("id") or f"shot_{shot.get('order', 1)}"); dest = target / f"{shot_id}.mp4"\n        download_video(video_url, dest)\n        result = AssetResult(path=str(dest), media_type=MEDIA_TYPE_VIDEO, source=self.name, model=self.model, seed=seed, prompt=prompt, first_frame_path=str(frame_path), cost=float(self.cost_per_call), event={"type":"video", "provider":self.name, "api_style":"tokendance", "remote_task_id":str(task_id), "duration":duration, "resolution":resolution})\n        result.validate(); return result\n\n    def _tokendance_request(self, url, method, body):\n        headers = {"Authorization": f"Bearer {self.api_key}", "Content-Type": "application/json"}\n        data = json.dumps(body, ensure_ascii=False).encode("utf-8") if body is not None else None\n        request = urllib.request.Request(url, data=data, headers=headers, method=method)\n        try:\n            with urllib.request.urlopen(request, timeout=60) as response: payload = json.loads(response.read().decode("utf-8"))\n        except urllib.error.HTTPError as exc:\n            detail = exc.read().decode("utf-8", errors="replace")[:500]; raise RuntimeError(f"TokenDance 图生视频 HTTP {exc.code}: {detail}") from exc\n        if not isinstance(payload, dict): raise RuntimeError("TokenDance 图生视频返回格式不是 JSON 对象")\n        return payload\n'''
if marker not in s: raise SystemExit('video marker missing')
s=s.replace(marker, helper+marker)
p.write_text(s,encoding='utf-8')

